/* Simplified, source-linked Open Category guidance reviewed 2026-11-10.
   No positive compliance determination; exemptions and Specific operations excluded. */
(function(root){
function review(p){const issues=[],guidance=[];const add=(title,text,source)=>guidance.push({title,text,source});const mass=Number(p.mass),height=Number(p.height),actual=Number(p.actualmass);const cls=p.classmark;const open=['A1','A2','A3'].includes(p.category);const sources={classes:'https://www.caa.co.uk/drones/open-category/getting-started-with-drones-and-model-aircraft/class-marks/',registration:'https://www.caa.co.uk/drones/open-category/drone-code/getting-what-you-need-to-fly-legally/',where:'https://www.caa.co.uk/drones/open-category/drone-code/where-you-can-fly-points-3-to-9/',vlos:'https://www.caa.co.uk/drones/open-category/drone-code/flying-safely-and-responsibly-points-1-and-2/',rid:'https://www.caa.co.uk/drones/open-category/moving-on-to-more-advanced-flying/remote-id-rid/',night:'https://www.caa.co.uk/drones/open-category/getting-started-with-drones-and-model-aircraft/flying-at-night-in-the-open-category/',insurance:'https://www.caa.co.uk/drones/open-category/moving-on-to-more-advanced-flying/insurance-requirements/',specific:'https://www.caa.co.uk/drones/specific-category/'};
const required=['classmark','mass','actualmass','camera','category','height','vlos','purpose','night'];const missing=required.filter(k=>!p[k]);if(p.category==='A2'&&!p.a2)missing.push('a2');
if(missing.length)issues.push('Complete the required operation profile ('+missing.length+' unanswered fields).');if(p.mass&&(!Number.isFinite(mass)||mass<=0))issues.push('Manufacturer MTOM must be a positive number.');if(p.actualmass&&(!Number.isFinite(actual)||actual<=0))issues.push('Planned take-off mass must be a positive number.');if(actual>mass&&mass>0)issues.push('Planned take-off mass exceeds the entered MTOM. Reduce payload or resolve the aircraft limits.');if(p.height&&(!Number.isFinite(height)||height<=0))issues.push('Height must be a positive number.');
if(p.category==='specific'){issues.push('Specific / other operations are outside this review. Apply your authorisation, limitations and operating procedures.');add('Authorisation-specific assessment','This app does not assess Specific, Certified or association authorisations.',sources.specific)}
if(open){if(height>120)issues.push('Planned height exceeds the ordinary Open Category 120 m limit. This app does not assess exceptions.');if(p.vlos==='no')issues.push('Direct VLOS is not confirmed. The ordinary Open planning scope is not satisfied.');if(mass>=25000)issues.push('Aircraft at or above 25 kg are outside the ordinary Open Category scope.');if(/^[UC](K)?[56]$/.test(cls))issues.push('Class 5/6 aircraft require an authorisation-specific assessment, outside this Open review.');if(cls==='private')issues.push('Privately built aircraft require a separate eligibility review; their additional conditions are not assessed here.');
const isLegacy=cls==='legacy'||(/^C[0-4]$/.test(cls)&&p.date>='2028-01-01');const n=/^(UK|C)([0-4])$/.exec(cls);const effective=n&&!isLegacy?Number(n[2]):null;
if(p.category==='A1'&&cls&&cls!=='private'&&!(effective===0||effective===1||(isLegacy&&mass>0&&mass<250)))issues.push('This class/mass does not match the ordinary A1 route described by the CAA.');
if(p.category==='A2'){if(p.a2!=='yes')issues.push('A2 requires a valid A2 Certificate of Competence; it is not confirmed.');if(cls&&cls!=='private'&&!(effective===2||(isLegacy&&mass>0&&mass<2000)))issues.push('This class/mass does not match the ordinary A2 route described by the CAA.');}
if(p.category==='A3'&&effective!==null&&effective<2)issues.push('CAA guidance assigns UK0/UK1 and recognised C0/C1 to A1; review the selected A3 route.');
if(cls==='legacy')add('Legacy aircraft','Verify eligibility, including when the aircraft was placed on the market. This app does not verify that history.',sources.classes);
if(/^C[0-4]$/.test(cls))add('European class transition',p.date<'2028-01-01'?'Corresponding C classes are recognised until 31 December 2027. Check the physical mark and documents.':'From 1 January 2028, C class aircraft use legacy weight-based routes; review current rules.',sources.classes);
const cap={UK0:250,UK1:900,UK2:4000,UK3:25000,UK4:25000,C0:250,C2:4000,C3:25000,C4:25000}[cls];if(cap&&mass>=cap)issues.push('Entered mass conflicts with the published weight overview for '+cls+'. Verify the aircraft documentation and limits.');
add('Height & terrain','Keep within 120 m of the nearest point of the earth’s surface, adjusting for terrain. This is not simply height above the launch point.',sources.where);add('Visual line of sight','Maintain direct VLOS and monitor surrounding airspace. Camera view alone is insufficient.',sources.vlos);
if(p.category==='A1')add('A1 · people','Eligible aircraft may operate closer to uninvolved people, but must never endanger them. Never fly over crowds.',sources.where);
if(p.category==='A2')add('A2 · people',isLegacy?'Legacy aircraft with MTOM below 2 kg: maintain at least 50 m horizontally from uninvolved people; no overflight.':'UK2 / recognised C2: maintain at least 30 m from uninvolved people; reduction to 5 m requires low-speed mode and the applicable risk assessment. No uninvolved-person overflight.', 'https://regulatorylibrary.caa.co.uk/2019-947/Content/map/00330_UAS.OPEN.030_UAS_operations_in_subcategory_A2.htm');
if(p.category==='A3')add('A3 · people & areas','Keep at least 50 m horizontally from uninvolved people, without overflight, and 150 m from residential, recreational, commercial and industrial areas. Keep 50 m from isolated buildings as defined by the CAA. Increase separation where safety requires.',sources.where);
}
if(mass>0){let flyer=mass>=100||/^UK[1-6]$/.test(cls),operator=mass>=250||(mass>=100&&p.camera==='yes')||/^UK[1-6]$/.test(cls);add('IDs & competence',(flyer?'Valid UK Flyer ID required. ':'Below 100 g: Flyer ID recommended. ')+(operator?'Operator ID required; check registration and aircraft labelling. ':'Check whether Operator ID is required, including organisational operation. ')+'A2 additionally requires a valid A2 CofC.',sources.registration)}
if(cls){let rid=/^UK[12356]$/.test(cls);add('Remote ID',rid?'For this UK class, Remote ID is mandatory from 1 January 2026: configure it correctly and keep it active. Check any applicable exemption.':'Check the CAA Remote ID table for the aircraft and operation. Legacy and European class aircraft have transitional arrangements; wider requirements apply from 1 January 2028. Enable it earlier where available.',sources.rid)}
if(p.night)add('Night operations',p.night==='yes'?'Open Category night flights require a green flashing light active throughout the flight; maintain VLOS and include the light in aircraft mass.':'If the flight could extend into night, reassess lighting and VLOS. Sunrise/sunset alone does not determine legal night.',sources.night);
if(p.purpose)add('Insurance',p.purpose==='work'?'Work, survey, research and educational use require appropriate third-party insurance meeting applicable Regulation (EU) 785/2004 requirements. Verify cover with your insurer.':'For recreation-only flying, check insurance applicability. Recreational aircraft at or above 20 kg need separate insurance review; third-party cover remains advisable.',sources.insurance);
return {issues,guidance,incomplete:missing.length>0,open};}
root.flightReview=review;if(typeof module!=='undefined')module.exports=review;
})(typeof window!=='undefined'?window:globalThis);
